import json, sys
d = json.load(open(sys.argv[1]))["series"]
mapped = set(json.load(open(sys.argv[2]))["series_map"].values())
WIN = {"A(2017Q1)": (2016, 2017, 2020), "B(2017Apr-Dec)": (2016, 2018, 2021), "C(2018Q1)": (2017, 2018, 2021),
       "D(2018Apr-Dec)": (2017, 2019, 2022), "E(2019Q1)": (2018, 2019, 2022)}
out = []
for s, v in d.items():
    if s in mapped: continue
    y = {int(a): b for a, b in v["years"].items()}; mo = {int(a): b for a, b in v["months"].items()}
    first = int(v["meta"]["车型最早上市日期"] or 0)
    ok = []
    for name, (b, y1, y4) in WIN.items():
        yrs = [b] + list(range(y1, y4 + 1))
        if all(mo.get(k, 0) == 12 for k in yrs) and min(y[k] for k in yrs) >= 1000 and first < b:
            ok.append(name[0])
    if ok:
        out.append((v["meta"]["品牌原产国"], s, v["meta"]["品牌"], first, "".join(ok), y.get(2017, 0), y.get(2018,0)))
out.sort(key=lambda r: (r[0] != "中国", -r[6]))
print(len(out), sum(r[0]=="中国" for r in out))
for r in out: print(*r)
EOF
python3 -I $S/scripts/windows.py $S/srni_agg.json $W/data/external/chinese_pairs/srni_car_manifest.json

